parameters.jsCode:
// Mode: Run Once for All Items

// Read from specific nodes
const parentItems   = $items('When Executed by Another Workflow') ?? [];
const defaultItems  = $items('Default values') ?? [];

// Helper: first non-empty array for a key
function firstArray(items, key) {
  for (const it of items) {
    const v = it?.json?.[key];
    if (Array.isArray(v) && v.length > 0) return v;
  }
  return null;
}

// Preferred: scenes from parent
const scenesFromParent = firstArray(parentItems, 'scenes');

// Fallbacks for scenes_temp
const scenesTempFromParent   = firstArray(parentItems, 'scenes_temp');
const scenesTempFromDefaults = firstArray(defaultItems, 'scenes_temp');

// Decide final
let finalScenes, source;
if (Array.isArray(scenesFromParent) && scenesFromParent.length > 0) {
  finalScenes = scenesFromParent;
  source = 'scenes@When Executed by Another Workflow';
} else if (Array.isArray(scenesTempFromParent) && scenesTempFromParent.length > 0) {
  finalScenes = scenesTempFromParent;
  source = 'scenes_temp@When Executed by Another Workflow';
} else if (Array.isArray(scenesTempFromDefaults) && scenesTempFromDefaults.length > 0) {
  finalScenes = scenesTempFromDefaults;
  source = 'scenes_temp@Default values';
} else {
  finalScenes = [];
  source = 'none';
}

// Debug logs
console.log(`✅ Using ${source}`);
console.log(`Total scenes: ${finalScenes.length}`);

return [{
  json: {
    final_scenes: finalScenes,
    meta: {
      source,
      total: finalScenes.length,
    },
  },
}];

